// Renders the committed email templates with sample values and screenshots them, light and dark:
//   pnpm email:preview                 every template, into .email-preview/ (gitignored)
//   pnpm email:preview magic_link      one template
//
// What it shows is the file Supabase sends (supabase/templates/*.html, generated by design/emails.mjs),
// with each Go-template variable replaced by the sample its email file names, once per language the mail speaks. A mail an edge function
// sends (`format = 'module'`, the waitlist invite) is read from its generated module, filled with its
// samples the same way, and shot once more with its optional blocks (`blocks`, the sign-up link)
// removed, as the function sends it without them. Dark is Chromium's
// `prefers-color-scheme: dark`, i.e. the <style> block's rules, the way Apple Mail or iOS Mail apply
// them. It cannot show Gmail's or Outlook's own rendering (docs/DEVELOPMENT.md, "Emails").
// Each template gets a phone-width and a desktop-width shot per scheme, plus the rendered .html.
import { mkdirSync, writeFileSync, readFileSync, readdirSync } from 'node:fs'
import { basename } from 'node:path'
import { pathToFileURL } from 'node:url'
import { chromium } from '@playwright/test'

const repo = new URL('../../', import.meta.url)
const out = new URL('../.email-preview/', import.meta.url)
mkdirSync(out, { recursive: true })

// The samples live next to the template's source, so a new email names its own variables.
const only = process.argv[2]
const names = readdirSync(new URL('design/emails/', repo))
  .filter((file) => file.endsWith('.mjs') && !['shell.mjs', 'color.mjs'].includes(file))
  .map((file) => basename(file, '.mjs'))
  .filter((name) => !only || name === only)
if (!names.length) throw new Error(`No email "${only}" in design/emails/.`)

/** The languages of a Go-template mail: the first is the `else`, each other has its `condition` (design/emails/magic_link.mjs). */
function splitBranches(file, email) {
  const [fallback, ...others] = email.languages ?? ['en']
  if (!others.length) return { [fallback]: file }
  const out = {}
  let rest = file
  for (const lang of others) {
    const open = email.condition[lang]
    if (!rest.startsWith(open)) throw new Error(`${email.output}: expected the ${lang} branch first`)
    const middle = rest.indexOf('{{ else }}')
    out[lang] = rest.slice(open.length, middle)
    rest = rest.slice(middle + '{{ else }}'.length)
  }
  out[fallback] = rest.replace(/\{\{ end \}\}$/, '')
  return out
}

const VIEWPORTS = { phone: { width: 390, height: 640 }, desktop: { width: 760, height: 640 } }

const browser = await chromium.launch()
try {
  for (const name of names) {
    const email = await import(pathToFileURL(new URL(`design/emails/${name}.mjs`, repo).pathname).href)
    const languages = email.languages ?? ['en']
    // Each language's mail, as the file holds it: a module has one string per language, the Go template
    // (magic_link.html) has them as the branches of `{{ if }} … {{ else }} … {{ end }}`.
    const templates =
      email.format === 'module'
        ? (await import(pathToFileURL(new URL(email.output, repo).pathname).href)).html
        : splitBranches(readFileSync(new URL(email.output, repo), 'utf8'), email)

    // The mail as sent, and, for a mail with optional blocks, without them; once per language.
    const variants = {}
    for (const lang of languages) {
      const samples = email.sample?.[lang] ?? email.sample ?? {}
      let filled = templates[lang]
      for (const [variable, value] of Object.entries(samples)) filled = filled.replaceAll(variable, value)
      const leftover = filled.match(/\{\{[^}]*\}\}/g)
      if (leftover) throw new Error(`${name} (${lang}): no sample for ${[...new Set(leftover)].join(', ')}`)
      const suffix = languages.length > 1 ? `-${lang}` : ''
      variants[`${name}${suffix}`] = filled
      if (email.blocks?.length) {
        let without = filled
        for (const block of email.blocks) without = without.replace(new RegExp(`<!--\\[${block}\\]-->[\\s\\S]*?<!--\\[/${block}\\]-->`, 'g'), '')
        variants[`${name}${suffix}-without-${email.blocks.join('-')}`] = without
      }
    }

    for (const [label, html] of Object.entries(variants)) {
      writeFileSync(new URL(`${label}.html`, out), html)
      for (const [size, viewport] of Object.entries(VIEWPORTS)) {
        for (const colorScheme of ['light', 'dark']) {
          const context = await browser.newContext({ viewport, colorScheme, deviceScaleFactor: 2 })
          const page = await context.newPage()
          await page.setContent(html)
          const file = `${label}-${size}-${colorScheme}.png`
          await page.screenshot({ path: new URL(file, out).pathname, fullPage: true })
          console.log(`✓ .email-preview/${file}`)
          await context.close()
        }
      }
    }
  }
} finally {
  await browser.close()
}
